  str_n28_15_name = "ST4 - Castigo",
  str_n28_1_name_desc = "/",
  str_n28_2_name_desc = "Un caso sobre una estatua decapitada está a su cargo, sin embargo, el reclamo del demandante no es daño a la propiedad pública, sino ... ¿obstrucción del amor?",
  str_n28_3_name_desc = "En esta estación, cuando el ardor del Día de la Corona de la Luna aún perdura en el aire, Tina tiene sus propios deseos de perseguir.",
  str_n28_4_name_desc = "¡Ve y experimenta el legendario Moonlight Salon, sumérgete en la atmósfera amorosa y descubre la verdad!",
  str_n28_5_name_desc = "/",
  str_n28_6_name_desc = "Solo cuando la vergüenza de Schwab se vuelve evidente, te das cuenta del terrible malentendido que ha ocurrido.",
  str_n28_7_name_desc = "Encuentras a la organizadora del salón, una monja ordinaria de Lumopolis, pero recibes algunas respuestas inesperadas.",
  str_n28_8_name_desc = "/",
  str_n28_9_name_desc = "Eclipses, en un momento como este? Realmente son criaturas tan extrañas...",
  str_n28_10_name_desc = "A medida que la amenaza de Eclipsite se acerca gradualmente a la estatua, ¡no olvides proteger la estatua en la batalla!",
  str_n28_11_name_desc = "¡Deshazte de los perseguidores que te persiguen y prepárate para luchar sin restricciones!",
  str_n28_12_name_desc = "¿¡Los sótanos de todos los nobles están llenos de tanta porquería!?",
  str_n28_13_name_desc = "No dejes que el más mínimo detalle pase desapercibido: ¡revela la verdad detrás del caso en el Salón de la Justicia!",
  str_n28_14_name_desc = "¡La corte está bajo el control absoluto de Schwab! Ya no hay posibilidad de que la justicia prevalezca aquí. ¡Primero debemos encontrar una salida a esto, luego pensar en otra forma!",
  str_n28_15_name_desc = "/",
  str_n28_1_name_desc_long = "Después del final del festival del Día de la Corona de la Luna, el persistente encanto del amor aún flota por las calles de Lumopolis. Una pareja enamorada llega al Salón de la Justicia y hace una escena. El caso incluso llama la atención de Schwartz, quien está presente para una inspección. Ante los cambios estructurales que se avecinan en el Salón de Justicia, varios jueces jóvenes exhiben reacciones diferentes:Leyn sigue trabajando sin darse cuenta, Matthieu te invita y Carleen para compartir un acontecimiento interesante, y Tina, que siempre está tan alegre, parece tener sus propias preocupaciones.",
  str_n28_2_name_desc_long = "El primer caso de la División de Romance que nadie está dispuesto a tratar está en tus manos. Una estatua ha sido decapitada y el demandante insiste en que la estatua sin vida es su amante. Vas a donde el Salón de Justicia guarda exhibiciones de casos e inspeccionas la estatua en busca de pistas. Fuera de la ventana, una \"luna\" se eleva en silencio.",
  str_n28_3_name_desc_long = "Sin pistas aparentes para seguir, Tina te invita a visitar su casa. Resulta que ella ha estado preocupada por algo durante bastante tiempo y espera que puedas ayudarla a que su plan de reunirse con él se haga realidad. Inmediatamente entiendes por las palabras de Tina que está secretamente enamorada de tu nuevo jefe, Schwab.",
  str_n28_4_name_desc_long = "Decides ir al Salón Moonlight para probar suerte y ver si puedes encontrar el objeto del afecto de Tina. Tina también trae un regalo que tiene la intención de darle. En el salón, bailas, conversas y disfrutas de las canciones festivas, pero el guardia de la ciudad de repente rompe este maravilloso momento. Los guardias están empeñados en reprimir esta reunión privada y, en medio del caos, se rompe otra estatua y se pierde el regalo de Tina.",
  str_n28_5_name_desc_long = "Inmediatamente te diriges al Salón de la Justicia para denunciar el asunto, pero te encuentras con otro par de amantes decididos a entablar una acalorada batalla legal. De hecho, los dos estaban presentes en el salón... Resulta que el regalo perdido de Tina provocó un malentendido entre ellos, y aunque Tina se apresura a explicar la situación, el asunto toma un giro inesperado...",
  str_n28_6_name_desc_long = "Debido al testimonio de Tina en la corte, Schwab termina avergonzado frente a todos. Después de salir del Salón de la Justicia, te das cuenta de que adivinaste demasiado rápido quién era el enamorado de Tina, según su explicación. El regalo nunca fue para Schwab, sino para el pequeño Eclipsite que parece aparecer en todas partes: Toto.",
  str_n28_7_name_desc_long = "Antes de que te prepares para partir, Loewe de repente trae una nueva perspectiva a Carleen en forma de nueva información. Parece que cada vez que se lleva a cabo el Salón de la Luz de la Luna, estallan disturbios y las cabezas de las estatuas desaparecen misteriosamente. A la luz de este avance, el organizador del Moonlight Salon parece muy sospechoso a tus ojos, pero cuando vuelves a encontrarte con el organizador, tus sospechas se disipan instantáneamente.",
  str_n28_8_name_desc_long = "Byron, el demandante en el caso de la estatua decapitada, acude al Salón de Justicia para presentar una denuncia y pide ver los resultados de la investigación lo antes posible. Recién sin pistas, los jueces reemplazan la cabeza cortada de la estatua en un acto de desesperación. Por supuesto, a Byron no le divierte un gesto tan descuidado, pero no tiene tiempo para permanecer enojado: su amada \"estatua de la esposa\" está en peligro. Los jueces se apresuran inmediatamente a la Escalera a los Cielos, donde está a punto de celebrarse un desfile.",
  str_n28_9_name_desc_long = "La estatua que requiere protección está en la parte superior de la escalera, en la dirección de la procesión que avanza. Para evitar que la estatua sea destruida en el caos, los jueces intentan detener el desfile por medios no convencionales. Justo cuando estás a punto de tener éxito, los eclipses comienzan a arrasar en la parte trasera del desfile y la multitud huye hacia la escalera.",
  str_n28_10_name_desc_long = "Intentas mantener la estatua a salvo. Los eclipses se acercan desde detrás de la multitud y el pánico los rodea. En el caos de la batalla, una mano sombría sale de la oscuridad y rompe la cabeza de la estatua, pero al menos Leyn se las arregla para sacar un guante de la mano del culpable desconocido. Byron, desconsolado, regresa al Salón de la Justicia, mientras que Schwab parece seguro de que tiene el caso cerrado y ordena el arresto de Tina.",
  str_n28_11_name_desc_long = "El guante obtenido por Leyn se convierte en la evidencia clave que apunta a la culpabilidad de Tina, y Schwab la arresta. Crees firmemente que Tina es inocente y no puede ignorar el extraño comportamiento de Schwab, ya que parece que la está incriminando. Tal vez si puedes averiguar sus motivos, puedes exonerarlo. Tina. Leyn decide arriesgarse y se cuela en la casa de Schwab para echar un vistazo.",
  str_n28_12_name_desc_long = "Entras a escondidas en la casa de Schwab para observarlo. Aunque el comportamiento de Schwab es algo extraño, no hay nada particularmente sospechoso en él. Abres el pasaje al sótano de Schwab por casualidad, y un enjambre de Eclipsites emerge de él. Huye de la casa de Schwab presa del pánico: el tiempo se acaba, a medida que se acerca el día del juicio.",
  str_n28_13_name_desc_long = "El juicio de las \"Decapitaciones de estatuas en serie\" finalmente comienza. Leyn y Matthieu insistir en que Tina es inocente, y después de una feroz defensa, Leyn se abalanza sobre la contradicción entre el guante y la mano de Tina, limpiando con éxito su nombre. Sin embargo, este asunto está lejos de terminar. Leyn invita a un testigo especial a subir al estrado. Toto ha venido al estrado de los testigos, listo para demostrar que el verdadero culpable es Schwab.",
  str_n28_14_name_desc_long = "Totó y Leyn planeó una estrategia ingeniosa de antemano, mediante la cual Toto fingió ser el culpable responsable de destrozar las estatuas, sacando a la luz con éxito el complot de Schwab. En su desesperación, Schwab revela su carta de triunfo: ¡ha reemplazado a los miembros del jurado con Eclipsites! Su veredicto no tiene nada que ver con la verdad. Escapas del Salón de la Justicia, pero te enfrentas a Schwab trastornado en la puerta. Al final, logras someterlo. El caso termina con el estallido del globo lunar: parece que la ola de romance que llena el aire se desvanecerá junto con él.",
  str_n28_15_name_desc_long = "Irridon vuelve a intentar el caso y condena a la parte culpable. Esta farsa era bastante inofensiva, por lo que Schwab no sería encarcelado. Aunque para él, el castigo que recibe puede ser incluso más insoportable que el encarcelamiento. Usted y los jueces también reciben un castigo simbólico por su comportamiento poco ortodoxo. Después de recibir el regalo de Tina, Toto está listo para emprender un nuevo viaje; su partida te hace esperar la próxima vez que te encuentres. Mientras los himnos flotan en el aire, Lumopolis vuelve a ser como antes.",
  str_n28_h1_name = "H1 - Embestida",
  str_n28_h2_name = "H2 - Estruendo mortal",
  str_n28_h3_name = "H3 - Resolver",
  str_n28_h4_name = "H4 - La persecución",
  str_n28_h5_name = "H5 - Inflexible",
  str_n28_h6_name = "H6 - La caballería",
  str_n28_h7_name = "EX1 - Esfuérzate por sobrevivir",
  str_n28_h8_name = "EX2 - Rayo abrasador",
  str_n28_h9_name = "EX3 - Sombras afiladas",
  str_n28_h10_name = "EX4 - Enjambre",
  str_n28_h11_name = "EX5 - Furia de sangre",
  str_n28_h12_name = "EX 6 - Golpe central",
  str_n28_h1_name_desc = "Los enemigos son esquivos y se mueven rápidamente, pero lo más aterrador es que están dispuestos a sacrificar sus vidas para derrotarte.",
  str_n28_h2_name_desc = "Truenos retumbantes llenan el aire. Cuando caen, tal vez puedas usar sus poderosas explosiones para atacar a los enemigos.",
  str_n28_h3_name_desc = "Aunque el enemigo es abrumador, con la ayuda de tus aliados, es posible que puedas cambiar el rumbo.",
  str_n28_h4_name_desc = "El terreno es complicado y tus enemigos son muchos, el simple hecho de salir con vida sería un milagro. ¡Cuidado con los enemigos que te persiguen!",
  str_n28_h5_name_desc = "Asediado por innumerables enemigos, ¿cómo puedes forjar un camino sangriento hacia la salvación? Además, una vez que estos enemigos mueren, se vuelven más y más fuertes...",
  str_n28_h6_name_desc = "Parecen Lumo Knights, pero bajo sus máscaras de piedra yacen viciosos Eclipsites. ¡No puedes permitirte caer!",
  str_n28_h7_name_desc = "Tus perseguidores están cada vez más cerca... ¿Cómo lograrán sobrevivir tus aliados?",
  str_n28_h8_name_desc = "Llamas y explosiones resonantes te rodean... El enemigo parece imbatible, pero el tiempo se convertirá en la clave de tu victoria.",
  str_n28_h9_name_desc = "Las sombras acechan en todos los rincones y las cuchillas afiladas buscan tu carne a cada paso. Te espera una dura batalla.",
  str_n28_h10_name_desc = "La inundación interminable de enemigos forma un enjambre hirviente, inundando desde el nido en el área central...",
  str_n28_h11_name_desc = "Las espadas del enemigo son tan afiladas como el viento cortante, y sus ataques son más letales que un vendaval furioso. Más aterrador que esto es el hecho de que una vez que están intoxicados por el olor a sangre, se vuelven aún más fuertes...",
  str_n28_h12_name_desc = "Aunque no estás absolutamente seguro, el enemigo que se encuentra en el centro del campo de batalla puede albergar intenciones ocultas...",
  str_n28_main_btn_unlock_time = "Desbloqueado después de {1}{2}{3}",
  str_n28_main_entry_tips3 = "Nuevo: Recopilación de pruebas",
  str_n28_main_entry_tips4 = "Nuevo: Marchitar",
  str_n28_name_1 = "¡Confiesa antes de que el mazo golpee!",
  str_n28_name_2 = "Admisiones Sinceras",
  str_n28_name_3 = "Cuando las Flores se Marchitan",
  str_n28_name_4 = "Recopilación de pruebas",
  str_n28_name_5 = "Amor a Prueba"
}
